INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(3500, 'individual', '/ˌɪndɪˈvɪdʒuəl/', 'noun, adjective', '{"zh-TW":["個人","個別的；個人的"],"en":["a single person","relating to one person"]}', NULL, 'individual needs/differences/rights', '[{"en":"Each individual is responsible for their own work.","zh-TW":"每個人要對自己的工作負責。"},{"en":"We offer individual attention to every client.","zh-TW":"我們為每位客戶提供個別關注。"}]', '{"noun":"individual, individuality","adjective":"individual","adverb":"individually"}', NULL, 4, 3500, 137),
(3501, 'indoctrination', '/ɪnˌdɒktrɪˈneɪʃən/', 'noun', '{"zh-TW":["灌輸；教化"],"en":["the process of teaching someone to accept a set of beliefs uncritically"]}', NULL, 'political indoctrination / religious indoctrination / resist indoctrination', '[{"en":"Critics accused the regime of using state media for political indoctrination.","zh-TW":"批評者指控該政權利用官方媒體進行政治灌輸。"},{"en":"Education should foster critical thinking, not indoctrination.","zh-TW":"教育應該培養批判性思維，而非灌輸思想。"}]', '{"verb":"indoctrinate","adjective":"indoctrinated"}', NULL, 5, 3501, NULL),
(3502, 'indoor track', '/''ɪndɔːr træk/', 'noun', '{"zh-TW":["室內跑道；田徑場"],"en":["a running track located inside a building or covered facility"]}', NULL, 'run on an indoor track / indoor track season / indoor track competition', '[{"en":"The athletes trained on the indoor track throughout the winter months.","zh-TW":"運動員在整個冬季在室內跑道上訓練。"},{"en":"An indoor track event differs from outdoor competition in distance and conditions.","zh-TW":"室內跑道賽事與戶外比賽在距離和條件上有所不同。"}]', NULL, NULL, 4, 3502, NULL),
(3503, 'induce', '/ɪnˈduːs/', 'verb', '{"zh-TW":["誘導；引起"],"en":["to persuade someone to do something; to cause"]}', NULL, 'induce changes/growth / induce someone to', '[{"en":"Nothing could induce him to change his mind.","zh-TW":"什麼都無法說服他改變主意。"},{"en":"The drug can induce drowsiness.","zh-TW":"這種藥物會引起嗜睡。"}]', '{"noun":"inducement, induction","verb":"induce"}', NULL, 2, 3503, NULL),
(3504, 'induction', '/ɪnˈdʌkʃən/', 'noun', '{"zh-TW":["入職培訓；就職儀式"],"en":["the process of introducing a new employee to the organization"]}', NULL, 'induction program / staff induction / induction training', '[{"en":"All new employees attend a two-day induction program.","zh-TW":"所有新員工參加為期兩天的入職培訓。"},{"en":"Induction training covers company policies and procedures.","zh-TW":"入職培訓涵蓋公司政策和程序。"}]', '{"verb":"induct"}', NULL, 3, 3504, NULL),
(3505, 'inductive', '/ɪnˈdʌktɪv/', 'adjective', '{"zh-TW":["歸納的；感應的"],"en":["relating to reasoning from specific observations to general conclusions"]}', NULL, 'inductive reasoning / inductive method / inductive logic', '[{"en":"Inductive reasoning forms the backbone of empirical science.","zh-TW":"歸納推理構成了實證科學的骨幹。"},{"en":"The study uses an inductive approach to theory building.","zh-TW":"該研究使用歸納方法進行理論建構。"}]', '{"noun":"induction","adverb":"inductively"}', NULL, 3, 3505, NULL),
(3506, 'industrial', '/ɪnˈdʌstriəl/', 'adjective', '{"zh-TW":["工業的；產業的"],"en":["relating to industry or manufacturing"]}', NULL, 'industrial area/zone/production', '[{"en":"The factory is located in an industrial zone.","zh-TW":"工廠位於工業區。"},{"en":"Industrial production has declined this quarter.","zh-TW":"本季度工業生產有所下降。"}]', '{"noun":"industry, industrialization","adjective":"industrial","verb":"industrialize"}', NULL, 4, 3506, NULL),
(3507, 'industrial action', '/ɪnˈdʌstriəl ˈækʃən/', 'noun', '{"zh-TW":["工業行動；罷工行動"],"en":["collective action by workers to protest or negotiate, such as a strike"]}', NULL, 'take industrial action / threatened industrial action', '[{"en":"Workers voted to take industrial action over the pay dispute.","zh-TW":"工人投票通過採取工業行動以抗議薪資糾紛。"},{"en":"The company sought to avoid industrial action by entering talks.","zh-TW":"公司尋求通過談判避免工業行動。"}]', NULL, NULL, 5, 3507, NULL),
(3508, 'industrialization', '/ɪnˌdʌstriəlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["工業化"],"en":["the development of industries in a country on a wide scale"]}', NULL, 'rapid industrialization / late industrialization / industrialization process', '[{"en":"Rapid industrialization in East Asia lifted millions out of poverty.","zh-TW":"東亞的快速工業化使數百萬人擺脫了貧困。"},{"en":"Industrialization transformed rural agricultural societies into urban manufacturing economies.","zh-TW":"工業化將農村農業社會轉變為城市製造業經濟體。"}]', '{"verb":"industrialize","adjective":"industrialized"}', NULL, 5, 3508, NULL),
(3509, 'industry', '/ˈɪndəstri/', 'noun', '{"zh-TW":["產業；工業","勤勉"],"en":["economic activity concerned with manufacturing","hard work"]}', NULL, 'the tourism/tech/finance industry', '[{"en":"The technology industry is growing rapidly.","zh-TW":"科技產業正在快速成長。"},{"en":"She is well-known in the fashion industry.","zh-TW":"她在時尚產業中很有名。"}]', '{"noun":"industry, industrialist","adjective":"industrial, industrious"}', NULL, 3, 3509, 370),
(3510, 'industry analysis', '/ˈɪndəstri əˈnæləsɪs/', 'noun', '{"zh-TW":["行業分析"],"en":["an assessment of the attractiveness and dynamics of an industry"]}', NULL, 'conduct industry analysis / industry analysis framework', '[{"en":"Porter''s Five Forces is a common framework for industry analysis.","zh-TW":"波特五力模型是行業分析的常用框架。"},{"en":"Industry analysis helps businesses identify opportunities and threats.","zh-TW":"行業分析幫助企業識別機會和威脅。"}]', NULL, NULL, 5, 3510, NULL),
(3511, 'industry benchmark', '/ˈɪndəstri ˈbentʃmɑːrk/', 'noun', '{"zh-TW":["行業基準"],"en":["a standard or point of reference against which industry performance is measured"]}', NULL, 'meet industry benchmarks / industry benchmark comparison / exceed industry benchmarks', '[{"en":"The company''s margins are well above industry benchmarks.","zh-TW":"公司的利潤率遠高於行業基準。"},{"en":"Industry benchmarks help identify areas where performance lags.","zh-TW":"行業基準幫助識別績效落後的領域。"}]', NULL, NULL, 5, 3511, NULL),
(3512, 'industry report', '/ˈɪndəstri rɪˈpɔːrt/', 'noun', '{"zh-TW":["行業報告"],"en":["an analysis of trends, competitors, and conditions in a specific industry"]}', NULL, 'publish an industry report / cite an industry report', '[{"en":"The industry report predicted 15% growth in cloud computing over 5 years.","zh-TW":"行業報告預測雲端運算在5年內增長15%。"},{"en":"Managers use industry reports to benchmark against peers.","zh-TW":"管理者使用行業報告與同業進行標竿比較。"}]', NULL, NULL, 5, 3512, NULL),
(3513, 'industry standard', '/ˈɪndəstri ˈstændərd/', 'noun', '{"zh-TW":["行業標準"],"en":["a widely accepted level of quality, performance, or practice in an industry"]}', NULL, 'meet industry standards / comply with industry standards', '[{"en":"The product was designed to comply with international industry standards.","zh-TW":"產品被設計為符合國際行業標準。"},{"en":"Industry standards ensure consistency and safety across products.","zh-TW":"行業標準確保了產品的一致性和安全性。"}]', NULL, NULL, 5, 3513, NULL),
(3514, 'inefficiency', '/ˌɪnɪˈfɪʃənsi/', 'noun', '{"zh-TW":["低效率；低效"],"en":["failure to make best use of time, money, or resources"]}', NULL, 'address inefficiencies / operational inefficiency', '[{"en":"The audit identified several inefficiencies in the procurement process.","zh-TW":"審計識別了採購流程中的幾個低效問題。"},{"en":"Inefficiency in logistics increased delivery costs significantly.","zh-TW":"物流低效顯著增加了配送成本。"}]', '{"adjective":"inefficient","adverb":"inefficiently"}', NULL, 4, 3514, NULL),
(3515, 'inertia', '/''ɪˌnɜːrʃə/', 'noun', '{"zh-TW":["慣性；不願改變的傾向"],"en":["a tendency to do nothing or to remain unchanged; resistance to change"]}', NULL, 'overcome inertia / organizational inertia / combat inertia', '[{"en":"Organizational inertia often prevents companies from adapting to changing market conditions.","zh-TW":"組織慣性往往使公司無法適應不斷變化的市場條件。"},{"en":"She struggled to overcome her inertia and finally began the project.","zh-TW":"她努力克服自己不願改變的傾向，最終開始了這個項目。"}]', '{"adjective":"inert","adverb":"inertly"}', NULL, 3, 3515, NULL),
(3516, 'inevitable', '/ɪnˈevɪtəbl/', 'adjective', '{"zh-TW":["不可避免的"],"en":["certain to happen; unavoidable"]}', '{"prefix":{"text":"in-","meaning":"not (不)"},"root":{"text":"evit","meaning":"avoid (避免)"},"suffix":{"text":"-able","meaning":"able to (能夠)"},"logic":"不能避免的。"}', 'inevitable result / inevitable change; inevitable consequence/result/outcome', '[{"en":"Change is inevitable in any organization.","zh-TW":"在任何組織中，變革都是不可避免的。"},{"en":"Delays were inevitable given the weather.","zh-TW":"考慮到天氣，延遲是不可避免的。"},{"en":"Change is inevitable in any organization.","zh-TW":"變革在任何組織中都是不可避免的。"},{"en":"It was inevitable that prices would rise.","zh-TW":"價格上漲是不可避免的。"}]', '{"adverb":"inevitably","noun":"inevitability","adjective":"inevitable"}', NULL, 4, 3516, NULL),
(3517, 'infer', '/ɪnˈfɜːr/', 'verb', '{"zh-TW":["推斷；推論"],"en":["to conclude from evidence and reasoning"]}', NULL, 'infer from / can be inferred', '[{"en":"We can infer from the data that sales are declining.","zh-TW":"我們可以從數據推斷出銷售額正在下降。"},{"en":"What can be inferred from this chart?","zh-TW":"從這張圖表中可以推斷出什麼？"}]', '{"noun":"inference","verb":"infer"}', NULL, 2, 3517, NULL),
(3518, 'inference', '/ˈɪnfərəns/', 'noun', '{"zh-TW":["推論；推斷"],"en":["a conclusion reached by reasoning from evidence"]}', NULL, 'draw an inference / make an inference / logical inference', '[{"en":"The inference from the study is that early intervention works.","zh-TW":"研究得出的推論是早期干預有效。"},{"en":"Incorrect inferences can arise from incomplete data sets.","zh-TW":"不完整的數據集可能導致錯誤的推論。"}]', '{"verb":"infer","adjective":"inferential"}', NULL, 3, 3518, NULL),
(3519, 'inferior', '/ɪnˈfɪriər/', 'adjective', '{"zh-TW":["較差的；次等的"],"en":["lower in quality, status, or rank"]}', NULL, 'inferior quality/product / feel inferior', '[{"en":"The cheaper product is inferior in quality.","zh-TW":"較便宜的產品品質較差。"},{"en":"Customers complained about inferior materials.","zh-TW":"客戶抱怨材料品質低劣。"}]', '{"noun":"inferiority","adjective":"inferior"}', NULL, 3, 3519, NULL),
(3520, 'infinite', '/''ɪnfɪnɪt/', 'adjective', '{"zh-TW":["無限的；無邊無際的"],"en":["limitless or endless in space, extent, or size; impossible to measure or calculate"]}', NULL, 'infinite possibilities / infinite patience / infinite resources', '[{"en":"The internet offers seemingly infinite possibilities for learning and creativity.","zh-TW":"互聯網為學習和創造力提供了看似無限的可能性。"},{"en":"She showed infinite patience while teaching children with learning difficulties.","zh-TW":"她在教導有學習困難的兒童時展示了無盡的耐心。"}]', '{"adverb":"infinitely","noun":"infinity"}', NULL, 3, 3520, NULL),
(3521, 'inflammation', '/ˌɪnfləˈmeɪʃən/', 'noun', '{"zh-TW":["發炎；炎症"],"en":["a localized physical condition with redness, swelling, and pain as reaction to injury or infection"]}', NULL, 'reduce inflammation / chronic inflammation / anti-inflammation', '[{"en":"Chronic inflammation is linked to cardiovascular disease and cancer.","zh-TW":"慢性炎症與心血管疾病和癌症有關。"},{"en":"The medication targets inflammation to relieve joint pain.","zh-TW":"藥物針對炎症來緩解關節疼痛。"}]', '{"adjective":"inflammatory","verb":"inflame"}', NULL, 4, 3521, NULL),
(3522, 'inflation', '/ɪnˈfleɪʃn/', 'noun', '{"zh-TW":["通貨膨脹"],"en":["a general increase in prices over time"]}', NULL, 'inflation rate / fight/curb inflation / rising inflation', '[{"en":"The inflation rate reached 8% this year.","zh-TW":"今年通貨膨脹率達到8%。"},{"en":"The central bank raised interest rates to combat inflation.","zh-TW":"央行提高利率以對抗通脹。"}]', '{"noun":"inflation","verb":"inflate","adjective":"inflationary"}', NULL, 3, 3522, NULL),
(3523, 'inflation hedge', '/ɪnˈfleɪʃən hedʒ/', 'noun', '{"zh-TW":["通脹對沖；抗通脹工具"],"en":["an investment designed to preserve value against inflation"]}', NULL, 'use as an inflation hedge / gold as an inflation hedge', '[{"en":"Real estate is often used as an inflation hedge.","zh-TW":"房地產常被用作通脹對沖工具。"},{"en":"Gold has traditionally served as an inflation hedge for investors.","zh-TW":"黃金傳統上作為投資者的通脹對沖工具。"}]', NULL, NULL, 5, 3523, NULL),
(3524, 'inflation rate', '/ɪnˈfleɪʃən reɪt/', 'noun', '{"zh-TW":["通貨膨脹率"],"en":["the percentage increase in the general price level over a period"]}', NULL, 'monitor the inflation rate / rising inflation rate', '[{"en":"Central banks raise interest rates to control a rising inflation rate.","zh-TW":"中央銀行提高利率以控制不斷上升的通貨膨脹率。"},{"en":"An inflation rate above 5% erodes consumer purchasing power.","zh-TW":"超過5%的通貨膨脹率侵蝕了消費者的購買力。"}]', '{"adjective":"inflationary"}', NULL, 5, 3524, NULL),
(3525, 'inflation targeting', '/ɪnˈfleɪʃən ˈtɑːrɡɪtɪŋ/', 'noun', '{"zh-TW":["通膨目標制"],"en":["a monetary policy strategy that sets a specific inflation rate as a goal"]}', NULL, 'adopt inflation targeting / inflation targeting framework / inflation targeting policy', '[{"en":"The central bank adopted an inflation targeting framework with a two percent annual goal.","zh-TW":"中央銀行採用了以每年百分之二為目標的通膨目標框架。"},{"en":"Inflation targeting provides clarity and predictability for financial markets.","zh-TW":"通膨目標制為金融市場提供了清晰度和可預測性。"}]', NULL, NULL, 5, 3525, NULL),
(3526, 'inflation-adjusted', '/ɪnˈfleɪʃən əˈdʒʌstɪd/', 'adjective', '{"zh-TW":["經通膨調整的"],"en":["taking inflation into account to give the real value"]}', NULL, 'inflation-adjusted returns / inflation-adjusted income', '[{"en":"Inflation-adjusted wages showed a decline in real purchasing power.","zh-TW":"經通膨調整的薪資顯示實際購買力下降了。"},{"en":"Investors should evaluate inflation-adjusted returns to assess true gains.","zh-TW":"投資者應評估經通膨調整的回報以評估真實收益。"}]', NULL, NULL, 5, 3526, NULL),
(3527, 'inflationary pressure', '/ɪnˈfleɪʃənəri ˈprɛʃər/', 'noun', '{"zh-TW":["通脹壓力"],"en":["forces that tend to cause prices to rise in an economy"]}', NULL, 'manage inflationary pressure / face inflationary pressure', '[{"en":"Inflationary pressure forced the central bank to raise interest rates.","zh-TW":"通脹壓力迫使央行提高利率。"},{"en":"Energy costs are a major source of inflationary pressure.","zh-TW":"能源成本是通脹壓力的主要來源。"}]', NULL, NULL, 5, 3527, NULL),
(3528, 'inflection point', '/ɪnˈflekʃən pɔɪnt/', 'noun', '{"zh-TW":["轉折點"],"en":["a point at which a significant change in the rate or direction of something occurs"]}', NULL, 'reach an inflection point / market inflection point / critical inflection point', '[{"en":"The industry is at an inflection point as technology disrupts traditional models.","zh-TW":"隨著技術顛覆傳統模式，行業處於轉折點。"},{"en":"The speech marked an inflection point in the campaign.","zh-TW":"這次演講標誌著競選活動的轉折點。"}]', NULL, NULL, 5, 3528, NULL),
(3529, 'inflow', '/ˈɪnfloʊ/', 'noun', '{"zh-TW":["流入；流入量"],"en":["the movement of money or goods into a system or account"]}', NULL, 'cash inflow / capital inflow / increase inflows', '[{"en":"Strong cash inflows allowed the company to pay down debt quickly.","zh-TW":"強勁的現金流入使公司能夠快速還清債務。"},{"en":"Foreign capital inflows boosted the local currency.","zh-TW":"外國資本流入提振了本幣。"}]', '{"opposite":"outflow"}', NULL, 2, 3529, NULL),
(3530, 'influence', '/ˈɪnfluəns/', 'noun', '{"zh-TW":["影響","影響；影響力"],"en":["the capacity to have an effect on someone or something","the power to affect someone or something"]}', '{"prefix":{"text":"in-","meaning":"in (進入)"},"root":{"text":"flu","meaning":"flow (流)"},"suffix":{"text":"-ence","meaning":"state (狀態)"},"logic":"流入其中產生作用，即「影響」。"}', 'have influence / under the influence of / positive influence; have influence on / under the influence of', '[{"en":"Social media has a huge influence on young people.","zh-TW":"社群媒體對年輕人有巨大的影響。"},{"en":"She used her influence to get the job.","zh-TW":"她利用自己的影響力得到了這份工作。"},{"en":"Social media has a huge influence on consumer behavior.","zh-TW":"社群媒體對消費者行為有巨大影響。"},{"en":"His research influenced the field significantly.","zh-TW":"他的研究對該領域產生了重大影響。"}]', '{"verb":"influence","adjective":"influential","noun":"influence"}', NULL, 3, 3530, NULL),
(3531, 'influencer', '/ˈɪnfluənsər/', 'noun', '{"zh-TW":["網路紅人；意見領袖"],"en":["a person who influences others through social media"]}', NULL, 'social media influencer / partner with an influencer', '[{"en":"The company partnered with influencers to promote the product.","zh-TW":"公司與網路紅人合作推廣產品。"},{"en":"Influencer marketing has become a major advertising strategy.","zh-TW":"網紅行銷已成為主要的廣告策略。"}]', '{"verb":"influence","adjective":"influential"}', NULL, 4, 3531, NULL),
(3532, 'influencer marketing', '/ˈɪnfluənsər ˈmɑːrkɪtɪŋ/', 'noun', '{"zh-TW":["網紅行銷；影響者行銷"],"en":["partnering with influential individuals to promote products"]}', NULL, 'influencer marketing campaign / micro-influencer marketing', '[{"en":"The brand''s influencer marketing campaign went viral.","zh-TW":"該品牌的網紅行銷活動爆紅。"},{"en":"Micro-influencer marketing often yields higher engagement rates.","zh-TW":"微型網紅行銷通常產生更高的互動率。"}]', '{"noun":"influencer"}', NULL, 5, 3532, NULL),
(3533, 'inform', '/ɪnˈfɔːrm/', 'verb', '{"zh-TW":["通知；告知"],"en":["to give someone facts or information"]}', NULL, 'inform someone of/about / keep informed', '[{"en":"Please inform us of any changes to your schedule.","zh-TW":"如果您的行程有變，請通知我們。"},{"en":"We will keep you informed of the progress.","zh-TW":"我們會隨時向您通報進展。"}]', '{"noun":"information","verb":"inform","adjective":"informative, informed"}', NULL, 2, 3533, 138),
(3534, 'informal communication', '/''ɪnˈfɔːrməl kəˌmjuːnɪˈkeɪʃən/', 'noun', '{"zh-TW":["非正式溝通；非正式交流"],"en":["communication that takes place outside of formal channels, often between colleagues or friends"]}', NULL, 'engage in informal communication / value informal communication / informal communication style', '[{"en":"Informal communication in the workplace can foster collaboration and innovation.","zh-TW":"工作場所的非正式溝通可以促進協作和創新。"},{"en":"She preferred informal communication, believing that it built stronger relationships.","zh-TW":"她偏好非正式溝通，認為它能建立更強大的關係。"}]', NULL, NULL, 5, 3534, NULL),
(3535, 'information', 'ˌɪnfərˈmeɪʃən', 'noun', '{"zh-TW":["信息；資訊","情報"],"en":["facts or knowledge","data"]}', NULL, 'provide information/background information', '[{"en":"For more information, visit our website.","zh-TW":"如需更多信息，請訪問我們的網站。"}]', '{"verb":"inform","adjective":"informative","adverb":"informatively"}', NULL, 4, 3535, NULL),
(3536, 'information asymmetry', '/ˌɪnfəˈmeɪʃən æˈsɪmɪtri/', 'noun', '{"zh-TW":["信息不對稱"],"en":["a situation where one party has more or better information than another"]}', NULL, 'reduce information asymmetry / information asymmetry in markets', '[{"en":"Information asymmetry in insurance can lead to adverse selection.","zh-TW":"保險中的信息不對稱可能導致逆向選擇。"},{"en":"Disclosure requirements reduce information asymmetry between companies and investors.","zh-TW":"披露要求減少了公司和投資者之間的信息不對稱。"}]', NULL, NULL, 5, 3536, NULL),
(3537, 'information disclosure', '/ˌɪnfəˈmeɪʃən dɪˈskloʊʒər/', 'noun', '{"zh-TW":["資訊披露"],"en":["the act of making information available to stakeholders or the public"]}', NULL, 'require information disclosure / information disclosure requirements', '[{"en":"Regulatory frameworks require timely information disclosure by listed firms.","zh-TW":"監管框架要求上市公司及時進行資訊披露。"},{"en":"Information disclosure protects investors from fraud and misrepresentation.","zh-TW":"資訊披露保護投資者免受詐欺和虛假陳述。"}]', NULL, NULL, 5, 3537, NULL),
(3538, 'information technology', '/ˌɪnfəˈmeɪʃən tekˈnɒlədʒi/', 'noun', '{"zh-TW":["資訊技術；資訊科技"],"en":["the use of systems and computers to store, process, and communicate data"]}', NULL, 'invest in information technology / information technology department', '[{"en":"The information technology budget was increased to support digital transformation.","zh-TW":"為支持數位轉型，資訊技術預算增加了。"},{"en":"Information technology improvements reduced processing time by half.","zh-TW":"資訊技術改進將處理時間縮短了一半。"}]', '{"abbreviation":"IT"}', NULL, 5, 3538, NULL),
(3539, 'informative', '/''ɪnˈfɔːrmətɪv/', 'adjective', '{"zh-TW":["資訊豐富的；有啟發性的"],"en":["providing useful information; instructive"]}', NULL, 'informative presentation / informative article / highly informative', '[{"en":"The workshop was highly informative and taught participants practical skills.","zh-TW":"這次研討會內容豐富，教導了參與者實用技能。"},{"en":"She wrote an informative guide to help customers understand the new product.","zh-TW":"她撰寫了一本資訊豐富的指南，幫助客戶了解新產品。"}]', '{"adverb":"informatively","noun":"information"}', NULL, 4, 3539, NULL),
(3540, 'informed', 'ɪnˈfɔːrmd', 'adjective', '{"zh-TW":["知情的；了解的","消息靈通的"],"en":["having the right information","up to date"]}', NULL, 'well-informed/keep informed', '[{"en":"Please keep all stakeholders informed.","zh-TW":"請讓所有利益相關者保持知情。"}]', '{"verb":"inform","noun":"information"}', NULL, 3, 3540, NULL),
(3541, 'infrastructure', '/ˈɪnfrəstrʌktʃər/', 'noun', '{"zh-TW":["基礎設施"],"en":["the basic systems and services that a country needs to function"]}', NULL, 'transportation/IT infrastructure', '[{"en":"The government invested heavily in infrastructure.","zh-TW":"政府大力投資基礎設施。"},{"en":"Poor infrastructure hinders economic development.","zh-TW":"落後的基礎設施阻礙了經濟發展。"}]', '{"noun":"infrastructure"}', NULL, 5, 3541, 371),
(3542, 'infrastructure as code', '/ˈɪnfrəstrʌktʃər æz kəʊd/', 'noun', '{"zh-TW":["基礎設施即代碼"],"en":["the practice of managing and provisioning infrastructure through code"]}', NULL, 'adopt infrastructure as code / infrastructure as code tool / infrastructure as code pipeline', '[{"en":"Infrastructure as code enables reproducible and version-controlled environments.","zh-TW":"基礎設施即代碼能夠實現可重現和版本控制的環境。"},{"en":"Teams use infrastructure as code to eliminate manual configuration errors.","zh-TW":"團隊使用基礎設施即代碼消除手動配置錯誤。"}]', NULL, NULL, 5, 3542, NULL),
(3543, 'infrastructure bond', '/ˈɪnfrəstrʌktʃər bɒnd/', 'noun', '{"zh-TW":["基礎設施債券"],"en":["a bond issued to finance infrastructure projects such as roads or utilities"]}', NULL, 'invest in infrastructure bonds / infrastructure bond yield', '[{"en":"Pension funds seek infrastructure bonds for long-term stable income.","zh-TW":"養老基金尋求基礎設施債券以獲得長期穩定收入。"},{"en":"Infrastructure bonds often have government backing, making them lower risk.","zh-TW":"基礎設施債券通常有政府支持，使其風險較低。"}]', NULL, NULL, 5, 3543, NULL),
(3544, 'infrastructure investment', '/ˈɪnfrəstrʌktʃər ɪnˈvestmənt/', 'noun', '{"zh-TW":["基礎設施投資"],"en":["capital expenditure on physical or technological systems supporting operations"]}', NULL, 'make infrastructure investments / infrastructure investment plan', '[{"en":"Infrastructure investment improved network reliability across the country.","zh-TW":"基礎設施投資提高了全國網路可靠性。"},{"en":"Government infrastructure investment creates jobs and stimulates growth.","zh-TW":"政府基礎設施投資創造了就業機會並刺激了增長。"}]', NULL, NULL, 5, 3544, NULL),
(3545, 'infrastructure project', '/ˈɪnfrəˌstrʌktʃər ˈprɒdʒekt/', 'noun', '{"zh-TW":["基礎設施項目"],"en":["a large-scale project to build or improve roads, bridges, utilities, etc."]}', NULL, 'fund an infrastructure project / infrastructure project management', '[{"en":"The government launched a major infrastructure project to upgrade transport links.","zh-TW":"政府啟動了一項重大基礎設施項目以升級交通連接。"},{"en":"Infrastructure projects are typically financed through public-private partnerships.","zh-TW":"基礎設施項目通常通過公私合作方式融資。"}]', NULL, NULL, 5, 3545, NULL),
(3546, 'infusion', '/''ɪnˈfjuːʒən/', 'noun', '{"zh-TW":["浸泡茶；浸泡液"],"en":["a drink made by soaking leaves, herbs, or spices in liquid; the process of extracting flavors"]}', NULL, 'herbal infusion / cold infusion / flavor infusion', '[{"en":"Chamomile infusion is a popular natural remedy for promoting sleep.","zh-TW":"洋甘菊浸泡茶是促進睡眠的常用天然療法。"},{"en":"She prepared an infusion of ginger and lemon for its health benefits.","zh-TW":"她泡製了薑和檸檬的浸泡茶，以獲取其健康功效。"}]', '{"verb":"infuse"}', NULL, 3, 3546, NULL),
(3547, 'ingredient', '/ɪnˈɡriːdiənt/', 'noun', '{"zh-TW":["食材；成分"],"en":["any of the components of a dish or recipe"]}', NULL, 'fresh ingredient / key ingredient', '[{"en":"The chef uses only locally sourced ingredients.","zh-TW":"廚師只使用當地採購的食材。"},{"en":"List all ingredients in the dish for allergy purposes.","zh-TW":"列出菜餚中的所有食材以供過敏參考。"}]', NULL, NULL, 4, 3547, NULL),
(3548, 'inherent', '/ɪnˈhɪrənt/', 'adjective', '{"zh-TW":["固有的；內在的"],"en":["existing as a natural or permanent quality"]}', NULL, 'inherent risk/problem/weakness', '[{"en":"There are inherent risks in any investment.","zh-TW":"任何投資都有固有的風險。"},{"en":"The plan has some inherent weaknesses.","zh-TW":"該計劃有一些固有的弱點。"}]', '{"adjective":"inherent","adverb":"inherently"}', NULL, 3, 3548, NULL),
(3549, 'inherent conflict', '/ɪnˈhɪərənt ˈkɒnflɪkt/', 'noun', '{"zh-TW":["內在衝突；固有矛盾"],"en":["a conflict that arises naturally from the structure of a situation"]}', NULL, 'manage inherent conflict / inherent conflict of interest / address inherent conflict', '[{"en":"There is an inherent conflict between short-term profits and long-term sustainability.","zh-TW":"短期利潤和長期可持續性之間存在內在衝突。"},{"en":"Independent boards are designed to manage inherent conflicts in governance.","zh-TW":"獨立董事會旨在管理治理中的固有矛盾。"}]', NULL, NULL, 5, 3549, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(3550, 'inherent risk', '/ɪnˈhɪərənt rɪsk/', 'noun', '{"zh-TW":["固有風險"],"en":["the risk present before any controls or mitigations are applied"]}', NULL, 'assess inherent risk / inherent risk of a transaction', '[{"en":"The inherent risk of cash handling is higher without strong internal controls.","zh-TW":"在沒有強有力內部控制的情況下，現金處理的固有風險較高。"},{"en":"Auditors assess the inherent risk before planning audit procedures.","zh-TW":"審計師在規劃審計程序前評估固有風險。"}]', NULL, NULL, 5, 3550, NULL),
(3551, 'inherently', '/ɪnˈhɪərəntli/', 'adverb', '{"zh-TW":["天生地；本質上"],"en":["in a permanent, essential, or characteristic manner"]}', NULL, 'inherently complex / inherently valuable / inherently unstable', '[{"en":"The problem is inherently difficult because of conflicting objectives.","zh-TW":"由於目標相互衝突，這個問題本質上是困難的。"},{"en":"Cross-cultural communication is inherently prone to misunderstanding.","zh-TW":"跨文化交流本質上容易產生誤解。"}]', '{"adjective":"inherent","noun":"inherence"}', NULL, 4, 3551, NULL),
(3552, 'inhibit', '/ɪnˈhɪbɪt/', 'verb', '{"zh-TW":["抑制；阻止"],"en":["to prevent or slow down a process"]}', NULL, 'inhibit growth/development/creativity', '[{"en":"Fear of failure can inhibit creativity.","zh-TW":"對失敗的恐懼會抑制創造力。"},{"en":"The drug inhibits the growth of cancer cells.","zh-TW":"這種藥物抑制癌細胞的生長。"}]', '{"noun":"inhibition, inhibitor","verb":"inhibit"}', NULL, 3, 3552, NULL),
(3553, 'initial', '/ɪˈnɪʃl/', 'adjective, noun', '{"zh-TW":["最初的；開始的","首字母"],"en":["existing at the beginning","the first letter of a name"]}', NULL, 'initial stage/phase/reaction', '[{"en":"The initial results are very promising.","zh-TW":"初步結果非常有前景。"},{"en":"Please write your initials on each page.","zh-TW":"請在每頁寫上您的姓名縮寫。"}]', '{"noun":"initial","adjective":"initial","adverb":"initially","verb":"initiate"}', NULL, 3, 3553, NULL),
(3554, 'initial investment', '/ɪˈnɪʃəl ɪnˈvestmənt/', 'noun', '{"zh-TW":["初始投資；前期投入"],"en":["the funds committed at the start of a project or business"]}', NULL, 'recover the initial investment / initial investment requirement', '[{"en":"The initial investment in the plant was 10 million dollars.","zh-TW":"工廠的初始投資為1000萬元。"},{"en":"The payback period for the initial investment was estimated at four years.","zh-TW":"初始投資的回收期估計為四年。"}]', NULL, NULL, 5, 3554, NULL),
(3555, 'initial outlay', '/ɪˈnɪʃəl ˈaʊtleɪ/', 'noun', '{"zh-TW":["初始支出；前期投資"],"en":["the upfront cost required to begin a project or investment"]}', NULL, 'calculate the initial outlay / cover the initial outlay', '[{"en":"The initial outlay for the new equipment was $1.5 million.","zh-TW":"新設備的初始支出為150萬元。"},{"en":"A low initial outlay makes the investment more accessible to smaller firms.","zh-TW":"低初始支出使較小的公司更容易進行投資。"}]', NULL, NULL, 5, 3555, NULL),
(3556, 'initial public offering', '/ɪˈnɪʃəl ˈpʌblɪk ˈɒfərɪŋ/', 'noun', '{"zh-TW":["首次公開募股"],"en":["the first time a private company sells shares to the public on a stock exchange"]}', NULL, 'plan an initial public offering / initial public offering price', '[{"en":"The company raised $200 million in its initial public offering.","zh-TW":"公司通過首次公開募股籌集了2億元。"},{"en":"An initial public offering requires extensive regulatory disclosures.","zh-TW":"首次公開募股需要廣泛的監管披露。"}]', '{"abbreviation":"IPO"}', NULL, 5, 3556, NULL),
(3557, 'initiate', '/ɪˈnɪʃieɪt/', 'verb', '{"zh-TW":["發起；開始"],"en":["to cause a process or action to begin"]}', NULL, 'initiate a project/discussion/process', '[{"en":"The manager initiated a review of company policies.","zh-TW":"經理發起了公司政策的審查。"},{"en":"Who initiated the negotiations?","zh-TW":"是誰發起了談判？"}]', '{"noun":"initiation, initiative, initiator","verb":"initiate","adjective":"initial"}', NULL, 3, 3557, 694),
(3558, 'initiative', '/ɪˈnɪʃətɪv/', 'noun', '{"zh-TW":["主動性；倡議","主動性；倡議；計劃"],"en":["the ability to act independently","a new plan or program","the ability to act independently; a new plan to deal with a problem"]}', '{"prefix":{"text":"in-","meaning":"into (進入)"},"root":{"text":"it","meaning":"go (走)"},"suffix":{"text":"-iative","meaning":"relating to (相關的)"},"logic":"走進去開始行動的，即「主動性」。"}', 'take the initiative / new initiative / on one''s own initiative; take the initiative / a government initiative', '[{"en":"She took the initiative to organize the event.","zh-TW":"她主動組織了這場活動。"},{"en":"The government launched a new environmental initiative.","zh-TW":"政府推出了新的環保倡議。"},{"en":"She took the initiative to organize the event.","zh-TW":"她主動組織了這次活動。"},{"en":"The company launched a new green initiative.","zh-TW":"公司發起了一項新的綠色倡議。"}]', '{"noun":"initiative, initiation","verb":"initiate"}', NULL, 4, 3558, 139),
(3559, 'injunction', '/ɪnˈdʒʌŋkʃən/', 'noun', '{"zh-TW":["禁令；法院強制令"],"en":["a court order requiring someone to do or stop doing something"]}', NULL, 'seek an injunction / court injunction', '[{"en":"The court granted an injunction preventing the company from publishing.","zh-TW":"法院頒布了禁止該公司出版的禁令。"},{"en":"A temporary injunction was issued pending the full hearing.","zh-TW":"在全面聆訊前，法院發出了臨時禁令。"}]', NULL, NULL, 4, 3559, NULL),
(3560, 'injunctive relief', '/ɪnˈdʒʌŋktɪv rɪˈliːf/', 'noun', '{"zh-TW":["禁令救濟"],"en":["a court order compelling or preventing a particular action"]}', NULL, 'seek injunctive relief / obtain injunctive relief / temporary injunctive relief', '[{"en":"The company sought injunctive relief to stop the competitor from using its trade secrets.","zh-TW":"公司尋求禁令救濟，阻止競爭對手使用其商業秘密。"},{"en":"Injunctive relief is often used in intellectual property disputes.","zh-TW":"禁令救濟常用於智慧財產權糾紛中。"}]', NULL, NULL, 5, 3560, NULL),
(3561, 'inland freight', '/''ɪnlənd freɪt/', 'noun', '{"zh-TW":["內陸運輸；陸地貨運"],"en":["the transportation of goods within a country''s interior, away from ports and borders"]}', NULL, 'arrange inland freight / inland freight carrier / inland freight cost', '[{"en":"Inland freight by rail is often more economical than road transport for heavy goods.","zh-TW":"鐵路內陸運輸對重型貨物通常比公路運輸更經濟。"},{"en":"The company used inland freight services to distribute products from the central warehouse.","zh-TW":"公司使用內陸運輸服務從中央倉庫分發產品。"}]', NULL, NULL, 5, 3561, NULL),
(3562, 'inn', '/ɪn/', 'noun', '{"zh-TW":["旅館；客棧"],"en":["a small hotel, especially in the countryside"]}', NULL, 'country inn / village inn', '[{"en":"They stayed at a cozy country inn for the weekend.","zh-TW":"他們在週末住在一家舒適的鄉村旅館。"},{"en":"The inn has only twelve rooms and offers home-cooked meals.","zh-TW":"這家客棔只有十二間客房，提供家常菜餚。"}]', NULL, NULL, 1, 3562, NULL),
(3563, 'innate', '/''ɪˈneɪt/', 'adjective', '{"zh-TW":["天生的；與生俱來的"],"en":["inborn; natural; present since birth"]}', NULL, 'innate talent / innate ability / innate curiosity', '[{"en":"She had an innate ability to connect with people from all backgrounds.","zh-TW":"她天生就有與各種背景的人建立聯繫的能力。"},{"en":"His innate curiosity drove him to constantly explore and learn new things.","zh-TW":"他天生的好奇心驅使他不斷探索和學習新事物。"}]', '{"adverb":"innately"}', NULL, 2, 3563, NULL),
(3564, 'innate curiosity', '/ɪˈneɪt kjʊərɪˈɒsɪti/', 'noun', '{"zh-TW":["天生好奇心；天生求知欲"],"en":["a natural and inborn desire to learn about and understand things"]}', NULL, 'innate curiosity about / driven by innate curiosity / foster innate curiosity', '[{"en":"Her innate curiosity about science led her to pursue a career in research.","zh-TW":"她對科學的天生好奇心引導她追求研究方面的職業。"},{"en":"Teachers should nurture students'' innate curiosity rather than suppress it.","zh-TW":"教師應培養學生的天生好奇心，而不是壓制它。"}]', NULL, NULL, 5, 3564, NULL),
(3565, 'innovation', '/ˌɪnəˈveɪʃn/', 'noun', '{"zh-TW":["創新","創新；革新"],"en":["a new method, idea, or product"]}', '{"prefix":{"text":"in-","meaning":"in (進入)"},"root":{"text":"nov","meaning":"new (新)"},"suffix":{"text":"-ation","meaning":"process (過程)"},"logic":"引入新事物的過程，即「創新」。"}', 'drive innovation / technological innovation; technological/product innovation / drive innovation', '[{"en":"Innovation is key to staying competitive.","zh-TW":"創新是保持競爭力的關鍵。"},{"en":"The company is known for its technological innovations.","zh-TW":"這家公司以技術創新聞名。"},{"en":"The company is known for its innovation in design.","zh-TW":"該公司以設計創新聞名。"}]', '{"verb":"innovate","adjective":"innovative","noun2":"innovator","noun":"innovation, innovator"}', NULL, 4, 3565, 580),
(3566, 'innovation ecosystem', '/ˌɪnəˈveɪʃən ˈiːkəʊˌsɪstəm/', 'noun', '{"zh-TW":["創新生態系統"],"en":["a network of organizations and resources supporting innovation"]}', NULL, 'build an innovation ecosystem / thriving innovation ecosystem / nurture an innovation ecosystem', '[{"en":"Silicon Valley is the world''s most successful innovation ecosystem.","zh-TW":"矽谷是世界上最成功的創新生態系統。"},{"en":"Universities play a key role in fostering local innovation ecosystems.","zh-TW":"大學在培育當地創新生態系統中發揮著關鍵作用。"}]', NULL, NULL, 5, 3566, NULL),
(3567, 'innovative', '/ˈɪnəveɪtɪv/', 'adjective', '{"zh-TW":["創新的"],"en":["featuring new methods or ideas"]}', NULL, 'innovative approach/solution/technology', '[{"en":"The company is known for its innovative products.","zh-TW":"該公司以其創新產品聞名。"},{"en":"We need innovative solutions to complex problems.","zh-TW":"我們需要創新的解決方案來應對複雜問題。"}]', '{"noun":"innovation, innovator","adjective":"innovative","verb":"innovate"}', NULL, 4, 3567, 885),
(3568, 'inorganic growth', '/ˌɪnɔːˈɡænɪk ɡrəʊθ/', 'noun', '{"zh-TW":["非有機成長；外部成長"],"en":["growth achieved through mergers, acquisitions, or partnerships"]}', NULL, 'pursue inorganic growth / inorganic growth strategy / inorganic expansion', '[{"en":"The company pursued inorganic growth by acquiring several competitors.","zh-TW":"公司通過收購幾個競爭對手追求非有機成長。"},{"en":"Inorganic growth can be faster but riskier than organic expansion.","zh-TW":"非有機成長可能比有機擴張更快，但風險也更大。"}]', NULL, NULL, 5, 3568, NULL),
(3569, 'inpatient', '/ˈɪnpeɪʃənt/', 'noun', '{"zh-TW":["住院病患"],"en":["a patient who stays in a hospital for treatment"]}', NULL, 'inpatient care / inpatient treatment', '[{"en":"Inpatient care is required for serious surgeries.","zh-TW":"重大手術需要住院護理。"},{"en":"The hospital has 200 inpatient beds.","zh-TW":"這家醫院有200張住院病床。"}]', '{"adjective":"inpatient"}', NULL, 3, 3569, NULL),
(3570, 'input', '/ˈɪnpʊt/', 'noun, verb', '{"zh-TW":["投入；輸入","提供意見"],"en":["what is put in; contribution","to enter data"]}', NULL, 'provide input / input data', '[{"en":"We value your input on this project.","zh-TW":"我們重視您對這個項目的意見。"},{"en":"Please input your password to continue.","zh-TW":"請輸入您的密碼以繼續。"}]', '{"noun":"input","verb":"input"}', NULL, 2, 3570, 372),
(3571, 'input cost', '/ˈɪnpʊt kɒst/', 'noun', '{"zh-TW":["投入成本；原料成本"],"en":["the cost of materials or resources used in production"]}', NULL, 'manage input costs / rising input costs', '[{"en":"Rising input costs squeezed the manufacturer''s margins.","zh-TW":"上漲的投入成本壓縮了製造商的利潤率。"},{"en":"The company passed higher input costs on to customers through price increases.","zh-TW":"公司通過提高價格將更高的投入成本轉嫁給了客戶。"}]', NULL, NULL, 4, 3571, NULL),
(3572, 'inquire', '/ɪnˈkwaɪər/', 'verb', '{"zh-TW":["詢問；調查"],"en":["to ask for information"]}', NULL, 'inquire about / inquire into', '[{"en":"She called to inquire about the job opening.","zh-TW":"她打電話詢問職位空缺的事。"},{"en":"The committee will inquire into the matter.","zh-TW":"委員會將對此事進行調查。"}]', '{"noun":"inquiry","verb":"inquire"}', NULL, 3, 3572, NULL),
(3573, 'inquiry', '/ɪnˈkwaɪəri/', 'noun', '{"zh-TW":["詢問；調查"],"en":["a request for information; an official investigation"]}', NULL, 'make an inquiry / customer inquiry / public inquiry', '[{"en":"We received several inquiries about the new product.","zh-TW":"我們收到了幾份關於新產品的詢問。"},{"en":"A public inquiry was launched into the incident.","zh-TW":"對該事件展開了公開調查。"}]', '{"noun":"inquiry","verb":"inquire"}', NULL, 3, 3573, 35),
(3574, 'insert', '/ɪnˈsɜːrt/', 'verb, noun', '{"zh-TW":["插入；嵌入","插入物"],"en":["to put something inside something else","something inserted"]}', NULL, 'insert a clause/coin/key', '[{"en":"Please insert your card into the machine.","zh-TW":"請將卡片插入機器。"},{"en":"A new clause was inserted into the contract.","zh-TW":"合同中插入了一項新條款。"}]', '{"noun":"insert, insertion","verb":"insert"}', NULL, 2, 3574, NULL),
(3575, 'inside', '/ɪnˈsaɪd/', 'preposition', '{"zh-TW":["在…裡面"],"en":["in or into the interior of"]}', NULL, 'inside information / inside out', '[{"en":"He has inside knowledge of the deal.","zh-TW":"他有這筆交易的內部消息。"},{"en":"She knows the business inside out.","zh-TW":"她對這個業務瞭若指掌。"}]', '{"preposition":"inside","noun":"inside","noun2":"insider","adjective":"inside"}', NULL, 2, 3575, NULL),
(3576, 'insider trading', '/ˈɪnsaɪdər ˈtreɪdɪŋ/', 'noun', '{"zh-TW":["內線交易；內幕交易"],"en":["trading stocks using non-public information, which is illegal"]}', NULL, 'prohibit insider trading / insider trading investigation', '[{"en":"The executive was charged with insider trading after buying shares before the merger.","zh-TW":"高管在合並前購買股票後被指控內線交易。"},{"en":"Insider trading undermines investor confidence in capital markets.","zh-TW":"內線交易破壞了投資者對資本市場的信心。"}]', NULL, NULL, 5, 3576, NULL),
(3577, 'insight', '/ˈɪnsaɪt/', 'noun', '{"zh-TW":["洞察力；見解"],"en":["a deep understanding of something"]}', NULL, 'gain/provide insight into', '[{"en":"The report provides valuable insights into consumer behavior.","zh-TW":"該報告提供了關於消費者行為的寶貴見解。"},{"en":"She has keen insight into human nature.","zh-TW":"她對人性有敏銳的洞察力。"}]', '{"noun":"insight","adjective":"insightful"}', NULL, 3, 3577, NULL),
(3578, 'insightful', '/ˈɪnsaɪtfəl/', 'adjective', '{"zh-TW":["有見地的；有洞察力的"],"en":["having or showing a clear understanding of complex matters"]}', NULL, 'insightful analysis / insightful comment / insightful observation', '[{"en":"Her insightful analysis of the data earned wide praise.","zh-TW":"她對數據的有見地分析獲得了廣泛讚譽。"},{"en":"The book offers insightful perspectives on leadership styles.","zh-TW":"這本書對領導風格提供了有洞察力的觀點。"}]', '{"noun":"insight","adverb":"insightfully"}', NULL, 4, 3578, NULL),
(3579, 'insist', '/ɪnˈsɪst/', 'verb', '{"zh-TW":["堅持；堅決要求"],"en":["to demand something firmly"]}', NULL, 'insist on / insist that', '[{"en":"The client insisted on a full refund.","zh-TW":"客戶堅持要求全額退款。"},{"en":"We insist that all safety protocols be followed.","zh-TW":"我們堅持必須遵守所有安全規程。"}]', '{"noun":"insistence","verb":"insist","adjective":"insistent"}', NULL, 2, 3579, NULL),
(3580, 'insolvency', '/ɪnˈsɒlvənsi/', 'noun', '{"zh-TW":["破產；無力償債"],"en":["the state of being unable to pay debts"]}', NULL, 'risk of insolvency / declare insolvency', '[{"en":"The firm is at risk of insolvency.","zh-TW":"該公司面臨破產風險。"},{"en":"They filed for insolvency last quarter.","zh-TW":"他們上一季申請了破產。"}]', '{"noun":"insolvency","adjective":"insolvent"}', NULL, 4, 3580, NULL),
(3581, 'insolvency proceedings', '/ɪnˈsɒlvənsi prəˈsiːdɪŋz/', 'noun', '{"zh-TW":["破產程序；清盤程序"],"en":["the legal process used when a company cannot pay its debts"]}', NULL, 'initiate insolvency proceedings / insolvency proceedings court', '[{"en":"Creditors applied to court to commence insolvency proceedings.","zh-TW":"債權人向法院申請開始破產程序。"},{"en":"Insolvency proceedings determine how assets are distributed among creditors.","zh-TW":"破產程序確定資產如何在債權人之間分配。"}]', '{"synonym":"bankruptcy proceedings"}', NULL, 5, 3581, NULL),
(3582, 'insolvent', '/ɪnˈsɒlvənt/', 'adjective', '{"zh-TW":["資不抵債的；破產的"],"en":["unable to pay debts when they fall due"]}', NULL, 'declared insolvent / technically insolvent', '[{"en":"The company was declared insolvent after missing three payments.","zh-TW":"公司在錯過三次還款後被宣告資不抵債。"},{"en":"Insolvent businesses can apply for protection under insolvency law.","zh-TW":"資不抵債的企業可以根據破產法申請保護。"}]', '{"noun":"insolvency"}', NULL, 3, 3582, NULL),
(3583, 'insourcing', '/ˈɪnsɔːrsɪŋ/', 'noun', '{"zh-TW":["內包；回歸自辦"],"en":["bringing previously outsourced work back in-house"]}', NULL, 'insourcing decision / insourcing strategy', '[{"en":"Insourcing IT services gave the firm better control.","zh-TW":"將IT服務內包讓公司擁有更好的控制。"},{"en":"The trend toward insourcing reflects quality concerns.","zh-TW":"內包趨勢反映出對品質的關注。"}]', '{"verb":"insource"}', NULL, 4, 3583, NULL),
(3584, 'inspect', '/ɪnˈspekt/', 'verb', '{"zh-TW":["檢查；視察"],"en":["to look at something closely to assess its condition","to look at something carefully to check its condition"]}', '{"prefix":{"text":"in-","meaning":"in (仔細)"},"root":{"text":"spect","meaning":"look (看)"},"logic":"仔細查看，即「檢查」。"}', 'inspect the premises / inspect for damage; inspect a building/facility/product', '[{"en":"Officials inspected the building for safety violations.","zh-TW":"官員檢查了建築物是否有安全違規。"},{"en":"The mechanic inspected the engine.","zh-TW":"技師檢查了引擎。"},{"en":"The building was inspected for safety violations.","zh-TW":"大樓接受了安全違規檢查。"},{"en":"Officials inspected the factory last week.","zh-TW":"官員上週視察了工廠。"}]', '{"noun":"inspection","noun2":"inspector","verb":"inspect"}', NULL, 3, 3584, 140),
(3585, 'inspection', '/ɪnˈspekʃn/', 'noun', '{"zh-TW":["檢查；視察"],"en":["a careful examination of something"]}', NULL, 'safety/quality inspection / pass inspection', '[{"en":"The factory passed its annual safety inspection.","zh-TW":"工廠通過了年度安全檢查。"},{"en":"Regular inspections ensure product quality.","zh-TW":"定期檢查確保產品品質。"}]', '{"noun":"inspection, inspector","verb":"inspect"}', NULL, 4, 3585, 581),
(3586, 'install', '/ɪnˈstɔːl/', 'verb', '{"zh-TW":["安裝；設置"],"en":["to put equipment or software in place for use"]}', NULL, 'install software/equipment/a system', '[{"en":"We need to install the new software by Friday.","zh-TW":"我們需要在週五前安裝新軟體。"},{"en":"Solar panels were installed on the roof.","zh-TW":"太陽能板被安裝在屋頂上。"}]', '{"noun":"installation, installment","verb":"install"}', NULL, 3, 3586, NULL),
(3587, 'installation art', '/ˌɪnstəˈleɪʃən ɑːrt/', 'noun', '{"zh-TW":["裝置藝術"],"en":["large-scale, site-specific art works creating an immersive environment"]}', NULL, 'create installation art / interactive installation art / contemporary installation art', '[{"en":"The artist created an installation art piece that transformed the entire gallery.","zh-TW":"藝術家創作了一件改變整個畫廊的裝置藝術作品。"},{"en":"Installation art challenges the boundaries between artist, artwork, and audience.","zh-TW":"裝置藝術挑戰藝術家、藝術作品和觀眾之間的界限。"}]', NULL, NULL, 5, 3587, NULL),
(3588, 'installment', '/ɪnˈstɔːlmənt/', 'noun', '{"zh-TW":["分期付款"],"en":["one of several payments made over a period of time"]}', NULL, 'pay in installments / monthly installment', '[{"en":"You can pay for the equipment in monthly installments.","zh-TW":"你可以按月分期付款購買設備。"},{"en":"The first installment is due next week.","zh-TW":"第一期款項下週到期。"}]', '{"noun":"installment, installation","verb":"install"}', NULL, 4, 3588, NULL),
(3589, 'instalment', '/ɪnˈstɔːlmənt/', 'noun', '{"zh-TW":["分期付款額"],"en":["one of several regular payments made to settle a debt"]}', NULL, 'pay in instalments / instalment plan', '[{"en":"The equipment was purchased with a 24-month instalment plan.","zh-TW":"設備以24個月的分期付款計劃購買。"},{"en":"Monthly instalments make high-cost purchases more affordable.","zh-TW":"每月分期付款使高成本採購更加負擔得起。"}]', '{"verb":"install","synonym":"installment"}', NULL, 4, 3589, NULL),
(3590, 'instance', '/ˈɪnstəns/', 'noun', '{"zh-TW":["實例；情況"],"en":["an example or case of something"]}', NULL, 'for instance / in this instance', '[{"en":"There have been several instances of fraud.","zh-TW":"已經發生了幾起詐騙事件。"},{"en":"For instance, many companies now allow remote work.","zh-TW":"例如，許多公司現在允許遠端工作。"}]', '{"noun":"instance"}', NULL, 3, 3590, NULL),
(3591, 'instantiate', '/ɪnˈstænʃieɪt/', 'verb', '{"zh-TW":["例示；具體化"],"en":["to represent as an instance of a principle; to create an instance of"]}', NULL, 'instantiate a model / instantiate a concept / instantiate a class', '[{"en":"The case study instantiates the broader theoretical claim.","zh-TW":"案例研究例示了更廣泛的理論主張。"},{"en":"The developer instantiates the class with specific parameters.","zh-TW":"開發者用特定參數實例化該類。"}]', '{"noun":"instantiation","adjective":"instantiated"}', NULL, 4, 3591, NULL),
(3592, 'instead', '/ɪnˈstɛd/', 'adverb', '{"zh-TW":["代替；反而"],"en":["as an alternative"]}', NULL, 'instead of / use instead', '[{"en":"Let''s use email instead of fax.","zh-TW":"我們用電子郵件代替傳真吧。"},{"en":"Instead, we should focus on quality.","zh-TW":"相反地，我們應該著重品質。"}]', '{"adverb":"instead"}', NULL, 3, 3592, NULL),
(3593, 'instigation', '/ˌɪnstɪˈɡeɪʃən/', 'noun', '{"zh-TW":["唆使；煽動；倡議"],"en":["the act of bringing about or initiating something, often wrongdoing"]}', NULL, 'at the instigation of / criminal instigation / on someone''s instigation', '[{"en":"The riot was found to have occurred at the instigation of a radical group.","zh-TW":"暴動被認定是在一個激進團體的唆使下發生的。"},{"en":"The inquiry was launched at the instigation of the audit committee.","zh-TW":"調查是在審計委員會的倡議下啟動的。"}]', '{"verb":"instigate","noun2":"instigator"}', NULL, 4, 3593, NULL),
(3594, 'institute', '/ˈɪnstɪtuːt/', 'noun, verb', '{"zh-TW":["機構；研究所","制定；開始"],"en":["an organization for education or research","to introduce or establish"]}', NULL, 'research institute / institute changes/reforms', '[{"en":"She works at a research institute.","zh-TW":"她在一家研究機構工作。"},{"en":"The company instituted new security measures.","zh-TW":"公司制定了新的安全措施。"}]', '{"noun":"institute, institution","verb":"institute","adjective":"institutional"}', NULL, 3, 3594, NULL),
(3595, 'institution', '/ˌɪnstɪˈtuːʃn/', 'noun', '{"zh-TW":["機構；制度"],"en":["a large organization; an established system"]}', NULL, 'financial/educational institution', '[{"en":"Banks are important financial institutions.","zh-TW":"銀行是重要的金融機構。"},{"en":"Marriage is a social institution.","zh-TW":"婚姻是一種社會制度。"}]', '{"noun":"institution","adjective":"institutional","verb":"institutionalize"}', NULL, 4, 3595, NULL),
(3596, 'institutional framework', '/ˌɪnstɪˈtjuːʃənl ˈfreɪmwɜːrk/', 'noun', '{"zh-TW":["制度框架"],"en":["the formal rules, regulations, and organizations governing behavior"]}', NULL, 'establish an institutional framework / institutional framework for investment', '[{"en":"A stable institutional framework attracts long-term investment.","zh-TW":"穩定的制度框架吸引了長期投資。"},{"en":"The institutional framework ensures fair competition in the market.","zh-TW":"制度框架確保了市場中的公平競爭。"}]', NULL, NULL, 5, 3596, NULL),
(3597, 'institutional investor', '/ˌɪnstɪˈtjuːʃənl ɪnˈvestər/', 'noun', '{"zh-TW":["機構投資者"],"en":["organizations such as banks, funds, and pension funds that invest large sums"]}', NULL, 'attract institutional investors / institutional investor demand', '[{"en":"Institutional investors hold 60% of the company''s shares.","zh-TW":"機構投資者持有公司60%的股份。"},{"en":"Strong institutional investor support boosted confidence in the IPO.","zh-TW":"機構投資者的強力支持提升了對首次公開募股的信心。"}]', NULL, NULL, 5, 3597, NULL),
(3598, 'instruct', '/ɪnˈstrʌkt/', 'verb', '{"zh-TW":["指示；教導"],"en":["to direct or teach someone to do something"]}', NULL, 'instruct employees / instruct on procedure', '[{"en":"Please instruct the team on the new process.","zh-TW":"請指示團隊新的流程。"},{"en":"She instructed the interns on office procedures.","zh-TW":"她指導實習生了解辦公室程序。"}]', '{"noun":"instruction","noun2":"instructor","adjective":"instructed"}', NULL, 3, 3598, NULL),
(3599, 'instruction', '/ɪnˈstrʌkʃn/', 'noun', '{"zh-TW":["指示；說明；教學"],"en":["directions or orders; teaching"]}', NULL, 'follow instructions / give instructions', '[{"en":"Please read the instructions carefully before use.","zh-TW":"使用前請仔細閱讀說明。"},{"en":"He gave clear instructions to his team.","zh-TW":"他向團隊下達了明確的指示。"}]', '{"noun":"instruction, instructor","verb":"instruct","adjective":"instructive"}', NULL, 4, 3599, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(3600, 'instructor', '/ɪnˈstrʌktər/', 'noun', '{"zh-TW":["講師；教練"],"en":["a person who teaches"]}', NULL, 'driving instructor / fitness instructor', '[{"en":"The instructor explained the exercise.","zh-TW":"教練解釋了這個練習。"},{"en":"She works as a yoga instructor.","zh-TW":"她是一名瑜伽教練。"}]', '{"verb":"instruct","noun2":"instruction"}', NULL, 4, 3600, NULL),
(3601, 'instrument', '/ˈɪnstrəmənt/', 'noun', '{"zh-TW":["儀器；工具；樂器"],"en":["a tool or device; a means to achieve something"]}', NULL, 'financial instrument / measuring instrument', '[{"en":"The laboratory is equipped with precision instruments.","zh-TW":"實驗室配備了精密儀器。"},{"en":"Bonds are common financial instruments.","zh-TW":"債券是常見的金融工具。"}]', '{"noun":"instrument, instrumentation","adjective":"instrumental"}', NULL, 4, 3601, NULL),
(3602, 'insurance', '/ɪnˈʃʊrəns/', 'noun', '{"zh-TW":["保險"],"en":["an arrangement for compensation of loss or damage"]}', NULL, 'health/life/car insurance / insurance policy', '[{"en":"All employees receive health insurance benefits.","zh-TW":"所有員工都享有健康保險福利。"},{"en":"You should take out travel insurance.","zh-TW":"你應該購買旅行保險。"}]', '{"noun":"insurance, insurer","verb":"insure","adjective":"insured"}', NULL, 3, 3602, NULL),
(3603, 'insurance premium', '/ɪnˈʃʊərəns ˈpriːmiəm/', 'noun', '{"zh-TW":["保費"],"en":["the amount paid periodically to maintain an insurance policy"]}', NULL, 'pay insurance premium / reduce insurance premium / annual insurance premium', '[{"en":"The company pays the health insurance premium for all employees.","zh-TW":"公司為所有員工支付健康保險保費。"},{"en":"Premiums rose after the policyholder filed multiple claims.","zh-TW":"保單持有人多次申請索賠後，保費上漲了。"}]', NULL, NULL, 5, 3603, NULL),
(3604, 'intangible', '/ɪnˈtændʒɪbəl/', 'adjective', '{"zh-TW":["無形的；難以量化的"],"en":["not physical; not easily defined or measured"]}', NULL, 'intangible benefits / intangible value / intangible skills', '[{"en":"Brand reputation is an intangible asset with significant value.","zh-TW":"品牌聲譽是一項具有重大價值的無形資產。"},{"en":"The merger created intangible benefits such as knowledge sharing.","zh-TW":"合併創造了知識共享等無形利益。"}]', '{"opposite":"tangible","noun":"intangible"}', NULL, 4, 3604, NULL),
(3605, 'intangible asset', '/ɪnˈtændʒɪbl ˈæset/', 'noun', '{"zh-TW":["無形資產"],"en":["a non-physical asset such as a patent, brand, or copyright"]}', NULL, 'recognize intangible assets / intangible asset valuation', '[{"en":"Brands and patents are valuable intangible assets.","zh-TW":"品牌和專利是有價值的無形資產。"},{"en":"Intangible assets are often harder to value than physical ones.","zh-TW":"無形資產通常比有形資產更難估值。"}]', '{"plural":"intangible assets","antonym":"tangible asset"}', NULL, 5, 3605, NULL),
(3606, 'intangible assets', '/ɪnˈtændʒɪbəl ˈæsets/', 'noun', '{"zh-TW":["無形資產"],"en":["non-physical assets with long-term value such as patents and brand names"]}', NULL, 'value intangible assets / intangible assets amortization / report intangible assets', '[{"en":"Brands and patents are among the most valuable intangible assets.","zh-TW":"品牌和專利是最有價值的無形資產之一。"},{"en":"Intangible assets are often undervalued on traditional financial statements.","zh-TW":"無形資產在傳統財務報告中往往被低估。"}]', NULL, NULL, 5, 3606, NULL),
(3607, 'integral', '/ˈɪntɪɡrəl/', 'adjective', '{"zh-TW":["不可或缺的；完整的"],"en":["essential; necessary for completeness"]}', NULL, 'integral part/component of', '[{"en":"Technology is an integral part of modern business.","zh-TW":"技術是現代商業不可或缺的一部分。"},{"en":"Teamwork is integral to our success.","zh-TW":"團隊合作對我們的成功至關重要。"}]', '{"noun":"integrity, integration","adjective":"integral","verb":"integrate"}', NULL, 3, 3607, NULL),
(3608, 'integrate', '/ˈɪntɪɡreɪt/', 'verb', '{"zh-TW":["整合；融合","整合；融入"],"en":["to combine into a whole","to combine things so they work together"]}', '{"prefix":{"text":"in-","meaning":"in (在內)"},"root":{"text":"tegr","meaning":"whole (完整)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使成為完整的一體，即「整合」。"}', 'integrate into / fully integrated; integrate into / integrate systems/data', '[{"en":"The new system integrates all departments.","zh-TW":"新系統整合了所有部門。"},{"en":"Immigrants gradually integrate into society.","zh-TW":"移民逐漸融入社會。"},{"en":"The new system integrates all departments into one platform.","zh-TW":"新系統將所有部門整合到一個平台上。"},{"en":"Immigrants often struggle to integrate into society.","zh-TW":"移民常常難以融入社會。"}]', '{"noun":"integration","adjective":"integrated","verb":"integrate"}', NULL, 3, 3608, 373),
(3609, 'integrate operations', '/ˈɪntɪɡreɪt ˌɒpəˈreɪʃənz/', 'verb', '{"zh-TW":["整合業務；整合運營"],"en":["combining functions or systems of different entities into one unified operation"]}', NULL, 'successfully integrate operations / integrate acquired operations', '[{"en":"The company took two years to fully integrate the acquired operations.","zh-TW":"公司花了兩年時間全面整合收購的業務。"},{"en":"Integrating operations eliminated duplication and saved 5 million annually.","zh-TW":"整合業務消除了重複工作，每年節省了500萬元。"}]', NULL, NULL, 5, 3609, NULL),
(3610, 'integrated', 'ˈɪntɪɡreɪtɪd', 'adjective', '{"zh-TW":["集成的；整合的","一體化的"],"en":["combining parts into a whole","unified"]}', NULL, 'integrated system/integrated approach', '[{"en":"We use an integrated project management tool.","zh-TW":"我們使用集成的專案管理工具。"}]', '{"verb":"integrate","noun":"integration"}', NULL, 4, 3610, NULL),
(3611, 'integrated report', '/ˈɪntɪɡreɪtɪd rɪˈpɔːrt/', 'noun', '{"zh-TW":["整合報告"],"en":["a report combining financial and non-financial performance information"]}', NULL, 'publish an integrated report / integrated report framework', '[{"en":"The company''s integrated report covers financial, ESG, and governance data.","zh-TW":"公司的整合報告涵蓋了財務、ESG和治理數據。"},{"en":"An integrated report provides a comprehensive view of value creation.","zh-TW":"整合報告提供了價值創造的全面視角。"}]', NULL, NULL, 5, 3611, NULL),
(3612, 'integration', '/ˌɪntɪˈɡreɪʃən/', 'noun', '{"zh-TW":["整合；集成"],"en":["combining separate systems or software to work together"]}', NULL, 'system integration / API integration', '[{"en":"The integration of the new software took three weeks.","zh-TW":"新軟體的整合花了三週時間。"},{"en":"Seamless integration between platforms improves efficiency.","zh-TW":"平台之間的無縫整合提高了效率。"}]', '{"verb":"integrate","adjective":"integrated"}', NULL, 4, 3612, 582),
(3613, 'integrity', '/ɪnˈteɡrəti/', 'noun', '{"zh-TW":["正直；誠信","完整性"],"en":["the quality of being honest and morally upright","the state of being whole"]}', NULL, 'personal/professional integrity / data integrity', '[{"en":"He is known for his integrity and honesty.","zh-TW":"他以正直和誠實著稱。"},{"en":"We must ensure the integrity of the data.","zh-TW":"我們必須確保數據的完整性。"}]', '{"noun":"integrity","adjective":"integral"}', NULL, 3, 3613, NULL),
(3614, 'intellectual', '/ˌɪntəˈlektʃuəl/', 'adjective, noun', '{"zh-TW":["智力的；知識分子"],"en":["relating to the intellect; a person of high intelligence"]}', NULL, 'intellectual property / intellectual capital', '[{"en":"Intellectual property rights must be protected.","zh-TW":"知識產權必須受到保護。"},{"en":"The company invests heavily in intellectual capital.","zh-TW":"公司大力投資智力資本。"}]', '{"noun":"intellect, intellectual, intelligence","adjective":"intellectual","adverb":"intellectually"}', NULL, 4, 3614, NULL),
(3615, 'intellectual asset', '/ˌɪntəˈlektʃuəl ˈæset/', 'noun', '{"zh-TW":["智識資產；知識資產"],"en":["knowledge, information, and expertise that have economic value"]}', NULL, 'protect intellectual assets / value intellectual assets', '[{"en":"Patents and trade secrets are valuable intellectual assets.","zh-TW":"專利和商業機密是有價值的知識資產。"},{"en":"The company''s intellectual assets include proprietary software.","zh-TW":"公司的知識資產包括專有軟體。"}]', NULL, NULL, 5, 3615, NULL),
(3616, 'intellectual capital', '/ˌɪntəˈlɛktʃuəl ˈkæpɪtəl/', 'noun', '{"zh-TW":["智力資本；知識資本"],"en":["the intangible value of a company''s knowledge and skills"]}', NULL, 'develop intellectual capital / protect intellectual capital', '[{"en":"The company''s intellectual capital is its most valuable asset.","zh-TW":"公司的智力資本是其最有價值的資產。"},{"en":"Training programs help build intellectual capital across the organization.","zh-TW":"培訓計劃有助於在整個組織中建立智力資本。"}]', NULL, NULL, 5, 3616, NULL),
(3617, 'intellectual curiosity', '/''ɪntəˌlektʃuəl ˌkjʊərɪˌɒsɪti/', 'noun', '{"zh-TW":["求知慾；智識好奇心"],"en":["a strong desire to learn about and understand things, especially in an academic or intellectual context"]}', NULL, 'foster intellectual curiosity / intellectual curiosity driven / intellectual curiosity is key', '[{"en":"Intellectual curiosity drives researchers to explore new ideas and challenge existing theories.","zh-TW":"求知慾驅使研究人員探索新想法並挑戰現有理論。"},{"en":"Great teachers inspire intellectual curiosity in their students from an early age.","zh-TW":"優秀的教師從小就在學生中激發求知慾。"}]', '{"adjective":"intellectual","adjective2":"curious"}', NULL, 5, 3617, NULL),
(3618, 'intellectual property', '/ˌɪntəˈlektʃuəl ˈprɒpəti/', 'noun', '{"zh-TW":["智慧財產權"],"en":["creations of the mind protected by law, such as patents and trademarks"]}', NULL, 'protect intellectual property / intellectual property rights / intellectual property law', '[{"en":"The company filed for intellectual property protection on its invention.","zh-TW":"公司為其發明申請了智慧財產權保護。"},{"en":"Intellectual property theft is a major concern for tech companies.","zh-TW":"智慧財產權盜竊是科技公司的主要擔憂。"}]', '{"abbreviation":"IP"}', NULL, 5, 3618, NULL),
(3619, 'intellectual property right', '/ˌɪntəˈlektʃuəl ˈprɒpəti raɪt/', 'noun', '{"zh-TW":["知識產權"],"en":["legal rights protecting creations of the mind such as inventions and brand names"]}', NULL, 'protect intellectual property rights / intellectual property right infringement', '[{"en":"The company vigorously defends its intellectual property rights in all markets.","zh-TW":"公司在所有市場積極捍衛其知識產權。"},{"en":"Intellectual property right infringement can result in significant legal damages.","zh-TW":"知識產權侵犯可能導致重大法律損害賠償。"}]', '{"abbreviation":"IPR","synonym":"intellectual property"}', NULL, 5, 3619, NULL),
(3620, 'intellectual property rights', '/ˌɪntəˈlektʃuəl ˈprɒpərti raɪts/', 'noun', '{"zh-TW":["智慧財產權"],"en":["legal rights protecting creations of the mind"]}', NULL, 'protect intellectual property rights / license intellectual property rights', '[{"en":"The company vigorously protects its intellectual property rights.","zh-TW":"公司積極保護其智慧財產權。"},{"en":"Intellectual property rights are often the most valuable asset in tech companies.","zh-TW":"在科技公司中，智慧財產權往往是最有價值的資產。"}]', '{"abbreviation":"IPR"}', NULL, 5, 3620, NULL),
(3621, 'intelligence', '/ɪnˈtelɪdʒəns/', 'noun', '{"zh-TW":["智力；情報"],"en":["the ability to learn; secret information"]}', NULL, 'artificial intelligence / business intelligence / market intelligence', '[{"en":"Artificial intelligence is transforming many industries.","zh-TW":"人工智慧正在改變許多行業。"},{"en":"Business intelligence tools help analyze data.","zh-TW":"商業智慧工具有助於分析數據。"}]', '{"noun":"intelligence","adjective":"intelligent","adverb":"intelligently"}', NULL, 4, 3621, NULL),
(3622, 'intend', '/ɪnˈtend/', 'verb', '{"zh-TW":["打算；意圖"],"en":["to plan or mean to do something"]}', NULL, 'intend to do / be intended for', '[{"en":"We intend to expand our operations next year.","zh-TW":"我們打算明年擴大營運。"},{"en":"This product is intended for professional use.","zh-TW":"此產品專供專業使用。"}]', '{"noun":"intention, intent","verb":"intend","adjective":"intentional, intended","adverb":"intentionally"}', NULL, 2, 3622, NULL),
(3623, 'intense', '/ɪnˈtens/', 'adjective', '{"zh-TW":["強烈的；劇烈的"],"en":["very great or extreme in degree"]}', NULL, 'intense competition/pressure/heat', '[{"en":"The competition in this market is intense.","zh-TW":"這個市場的競爭非常激烈。"},{"en":"She felt intense pressure to meet the deadline.","zh-TW":"她感受到巨大的壓力要趕上截止日期。"}]', '{"noun":"intensity","adjective":"intense, intensive","verb":"intensify","adverb":"intensely"}', NULL, 3, 3623, NULL),
(3624, 'interact', '/ˌɪntərˈækt/', 'verb', '{"zh-TW":["互動；交流"],"en":["to communicate or work with others"]}', NULL, 'interact with customers/colleagues', '[{"en":"Employees interact with customers on a daily basis.","zh-TW":"員工每天都與客戶互動。"},{"en":"The software allows users to interact with the data.","zh-TW":"該軟體允許用戶與數據互動。"}]', '{"noun":"interaction","verb":"interact","adjective":"interactive"}', NULL, 3, 3624, 374),
(3625, 'interaction', 'ˌɪntərˈækʃən', 'noun', '{"zh-TW":["互動；交流","相互作用"],"en":["communication between people","a meeting of minds"]}', NULL, 'customer interaction/positive interaction', '[{"en":"Positive customer interactions build loyalty.","zh-TW":"積極的客戶互動建立忠誠度。"}]', '{"verb":"interact","adjective":"interactive","adverb":"interactively"}', NULL, 4, 3625, 583),
