(3627, 'interdisciplinary', '/ˌɪntərˈdɪsəplɪnəri/', 'adjective', '{"zh-TW":["跨學科的；跨領域的"],"en":["relating to more than one branch of knowledge"]}', NULL, 'interdisciplinary research / interdisciplinary team / interdisciplinary approach', '[{"en":"Climate change requires an interdisciplinary approach to solve.","zh-TW":"氣候變遷需要跨學科方法來解決。"},{"en":"The program encourages interdisciplinary collaboration across departments.","zh-TW":"該計畫鼓勵跨部門的跨學科合作。"}]', '{"noun":"interdisciplinarity"}', NULL, 5, 3627, NULL),
