(3629, 'interest coverage ratio', '/ˈɪntrəst ˈkʌvərɪdʒ ˈreɪʃioʊ/', 'noun', '{"zh-TW":["利息覆蓋率"],"en":["a ratio measuring a company''s ability to pay interest on its debt"]}', NULL, 'calculate the interest coverage ratio / strong interest coverage ratio', '[{"en":"A high interest coverage ratio indicates financial stability.","zh-TW":"高利息覆蓋率表明財務穩定性。"},{"en":"The company''s interest coverage ratio fell below 2, triggering concern.","zh-TW":"公司的利息覆蓋率跌破2，引發擔憂。"}]', NULL, NULL, 5, 3629, NULL),
(3630, 'interest income', '/ˈɪntrɪst ˈɪnkʌm/', 'noun', '{"zh-TW":["利息收入"],"en":["earnings generated from lending money or investing in interest-bearing instruments"]}', NULL, 'report interest income / interest income tax', '[{"en":"The company earns interest income from its surplus cash deposits.","zh-TW":"公司從其盈餘現金存款中獲得利息收入。"},{"en":"Interest income is taxable and must be disclosed in financial reports.","zh-TW":"利息收入須繳稅，並必須在財務報告中披露。"}]', NULL, NULL, 5, 3630, NULL),
