(3633, 'interest rate risk', '/ˈɪntrəst reɪt rɪsk/', 'noun', '{"zh-TW":["利率風險"],"en":["the risk that changes in interest rates will negatively affect finances"]}', NULL, 'manage interest rate risk / interest rate risk exposure', '[{"en":"The bond portfolio is exposed to significant interest rate risk.","zh-TW":"債券投資組合面臨重大利率風險。"},{"en":"The company uses swaps to hedge its interest rate risk.","zh-TW":"公司使用掉期合約對沖利率風險。"}]', NULL, NULL, 5, 3633, NULL),
