(3642, 'interlocutory', '/ˌɪntəˈlɒkjʊtəri/', 'adjective', '{"zh-TW":["中間性的；暫時性的"],"en":["(of a court decree or order) given during the course of a legal action"]}', NULL, 'interlocutory order / interlocutory injunction / interlocutory relief', '[{"en":"The court issued an interlocutory injunction to preserve the status quo.","zh-TW":"法院發出了維持現狀的中間禁令。"},{"en":"An interlocutory order is not a final judgment and may be appealed.","zh-TW":"中間命令不是最終判決，可以上訴。"}]', NULL, NULL, 5, 3642, NULL),
